#!/usr/bin/env python3
"""Generate the exact-width integer formatter used by std/strconv."""

import argparse
from pathlib import Path


OUTPUT = Path(__file__).resolve().parents[1] / "stdlib/strconv/integer_format.wz"


def generate():
    header = (
        "// Generated by tools/generate_integer_format_wz.py.\n"
        "package strconv;\n"
        'import "std/text" as text;\n\n'
    )
    out = ["// The literal tables cover single- and double-digit chunks without allocating."]
    for name, cases in (
        ("digit", [(i, str(i)) for i in range(10)]),
        ("negative_digit", [(i, f"-{i}") for i in range(10)]),
        ("pair", [(i, f"{i:02d}") for i in range(100)]),
    ):
        out += [f"func {name}(value u64) string {{", "    switch value {"]
        out.extend(f'        case {n}: return "{text}";' for n, text in cases)
        out += ['        default: return "";', "    }", "}", ""]
    out += ['''func format_decimal(magnitude u64, negative bool) string {
    if magnitude < 10 {
        if negative { return negative_digit(magnitude); }
        return digit(magnitude);
    }
    if magnitude < 100 {
        let digits = pair(magnitude);
        if negative { return "-" + digits; }
        return digits;
    }
    if !negative && magnitude < 10_000 {
        let prefix = magnitude / 100;
        let suffix = pair(magnitude % 100);
        if prefix < 10 { return digit(prefix) + suffix; }
        return pair(prefix) + suffix;
    }

    // An exact-size Vec literal initializes the digit bytes directly.
    // Reading the next digit stops as soon as the quotient reaches zero.
    var remaining = magnitude;
    try {''']
    for digit in range(20):
        out += [f"        let d{digit} = u8(remaining % 10) + 48;"]
        if digit < 19:
            out += ["        remaining /= 10;"]
        if digit < 2:
            continue
        digits = ", ".join(f"d{i}" for i in reversed(range(digit + 1)))
        if digit < 19:
            out += [
                "        if remaining == 0 {",
                f"            if negative {{ return text.from_bytes([u8(45), {digits}]); }}",
                f"            return text.from_bytes([{digits}]);",
                "        }",
            ]
        else:
            out += [f"        return text.from_bytes([{digits}]);"]
    out += ['''    } catch error text.Error {
        // The bytes above are decimal ASCII digits and an optional minus.
        return "";
    }
}

pub func format_i64(value i64) string {
    if value < 0 { return format_decimal(u64(-(value + 1)) + 1, true); }
    return format_decimal(u64(value), false);
}

pub func format_u64(value u64) string { return format_decimal(value, false); }
''']

    return header + "\n".join(out)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = generate().encode("utf-8")
    if args.check:
        if OUTPUT.read_bytes() != generated:
            raise SystemExit(f"{OUTPUT}: regenerate with {Path(__file__).name}")
        return
    OUTPUT.write_bytes(generated)


if __name__ == "__main__":
    main()
